package com.machinefault.api.service;

import com.machinefault.api.domain.*; import com.machinefault.api.repo.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.time.Instant; import java.util.*;

// Applies fault workflow rules and coordinates repositories and notifications.
@Service public class FaultService {
 private final FaultReportRepository reports; private final MachineRepository machines; private final UserRepository users; private final StatusChangeRepository history; private final MaintenanceActionRepository actions; private final AssignmentChangeRepository assignments; private final NotificationService notificationService;
 public FaultService(FaultReportRepository r,MachineRepository m,UserRepository u,StatusChangeRepository h,MaintenanceActionRepository a,AssignmentChangeRepository assignments,NotificationService notificationService){reports=r;machines=m;users=u;history=h;actions=a;this.assignments=assignments;this.notificationService=notificationService;}
 // Save the report, initial history, and notifications together so a partial submission is not left behind.
 @Transactional public FaultReport create(String machineId,String description,String username){Machine m=machines.findByIdentifierAndActiveTrue(machineId).orElseThrow(()->new NoSuchElementException("Machine identifier not found."));AppUser reporter=user(username);FaultReport r=reports.save(new FaultReport(m,description,reporter));m.setStatus(MachineStatus.FAULT_REPORTED);history.save(new StatusChange(r,null,FaultStatus.REPORTED,reporter));notificationService.newFault(r);return r;}
 @Transactional(readOnly=true) public Page<FaultReport> search(FaultStatus status,String machine,Long technician,Long reporter,Instant from,Instant to,int page,int size){if(from!=null&&to!=null&&!from.isBefore(to))throw new IllegalArgumentException("from must be earlier than to.");return reports.search(status,machine,technician,reporter,from,to,PageRequest.of(page,Math.min(size,100),Sort.by(Sort.Direction.DESC,"submittedAt")));}
 @Transactional(readOnly=true) public FaultReport get(Long id){return reports.findDetailedById(id).orElseThrow(()->new NoSuchElementException("Fault report not found."));}
 @Transactional(readOnly=true) public FaultReport getVisible(Long id,String username){FaultReport r=get(id);AppUser u=user(username);if(u.getRole()==UserRole.PRODUCTION_WORKER&&!r.getReporter().getId().equals(u.getId()))throw new NoSuchElementException("Fault report not found.");if(u.getRole()==UserRole.MAINTENANCE_TECHNICIAN&&(r.getAssignedTechnician()==null||!r.getAssignedTechnician().getId().equals(u.getId())))throw new NoSuchElementException("Fault report not found.");return r;}
 // Assignment changes keep their own history so reassigning never erases who had the report before.
 @Transactional public FaultReport assign(Long id,Long techId,String actor){FaultReport r=get(id);AppUser technician=users.findById(techId).orElseThrow(()->new NoSuchElementException("Technician not found."));if(technician.getRole()!=UserRole.MAINTENANCE_TECHNICIAN||!technician.isEnabled())throw new IllegalArgumentException("Select an active Maintenance Technician.");if(r.getStatus()!=FaultStatus.REPORTED&&r.getStatus()!=FaultStatus.ASSIGNED)throw new IllegalArgumentException("Only reported or assigned faults can be assigned.");AppUser by=user(actor);AppUser previous=r.getAssignedTechnician();FaultStatus before=r.getStatus();r.assign(technician);reports.save(r);history.save(new StatusChange(r,before,r.getStatus(),by));assignments.save(new AssignmentChange(r,previous,technician,by));r.getMachine().setStatus(MachineStatus.UNDER_MAINTENANCE);notificationService.assigned(r,technician);return r;}
 // Only the next step in the approved workflow is accepted; every accepted change is audited.
 @Transactional public FaultReport changeStatus(Long id,FaultStatus next,String actor){FaultReport r=get(id);AppUser by=user(actor);if(by.getRole()==UserRole.MAINTENANCE_TECHNICIAN&&(r.getAssignedTechnician()==null||!r.getAssignedTechnician().getId().equals(by.getId())))throw new IllegalArgumentException("You can only update reports assigned to you.");FaultStatus current=r.getStatus();boolean valid=switch(current){case REPORTED->next==FaultStatus.ASSIGNED;case ASSIGNED->next==FaultStatus.IN_PROGRESS;case IN_PROGRESS->next==FaultStatus.RESOLVED;case RESOLVED->next==FaultStatus.CLOSED;case CLOSED->false;};if(!valid)throw new IllegalArgumentException("Invalid status transition from "+current+" to "+next+".");r.setStatus(next);reports.save(r);history.save(new StatusChange(r,current,next,by));if(next==FaultStatus.CLOSED||next==FaultStatus.RESOLVED)r.getMachine().setStatus(MachineStatus.OPERATIONAL);else if(next==FaultStatus.IN_PROGRESS)r.getMachine().setStatus(MachineStatus.UNDER_MAINTENANCE);notificationService.statusChanged(r,next);return r;}
 // A technician may add work notes only to a report currently assigned to them.
 @Transactional public MaintenanceAction addAction(Long reportId,String description,String actor){FaultReport r=get(reportId);AppUser tech=user(actor);if(tech.getRole()!=UserRole.MAINTENANCE_TECHNICIAN||r.getAssignedTechnician()==null||!r.getAssignedTechnician().getId().equals(tech.getId()))throw new IllegalArgumentException("You can only record actions on reports assigned to you.");return actions.save(new MaintenanceAction(r,tech,description));}
 public AppUser user(String username){return users.findByUsername(username).orElseThrow(()->new NoSuchElementException("User not found."));}
}
